# -*- coding: utf-8 -*-
"""Saḷāyatanavagga — The Book of the Six Sense Fields (SN 35-44). One
discourse per page, with merged pages for peyyāla (formula-repetition)
ranges wherever bilara-data itself stores them as a single file."""

SC = "https://suttacentral.net"

INDEX_HEADING = "IV. Saḷāyatanavagga — The Book of the Six Sense Fields"
# Four pages from the original twenty-page curated selection fall within
# this book's own range (SN 35-44): SN 35.28 (Ādittasutta, "Burning"),
# SN 36.6 (Sallasutta, "An Arrow"), SN 41.1 (Saṃyojanasutta, "The
# Fetter"), and SN 42.8 (Saṅkhadhamasutta, listed on-site as "Kulaghara
# (Assāroha)", "A Horn Blower"). None of them sit at this book's own
# opening (SN 35.1) -- SN 35.28 falls mid-vagga inside Sabbavagga (SN
# 35.23-32), and the other three sit in saṃyuttas this module has not
# reached yet. Registered here in INDEX_EXTRA and not generated by this
# module; SN 35.28 will need the same "fragile junction" treatment Book
# II and Book III discovered (SN 12.15, SN 22.59, SN 22.87 and others):
# once Sabbavagga is generated, sn_build.py's auto-chain will skip
# straight over SN 35.28's own pre-existing page, and its neighbours'
# prev/next must be hand-patched after every single build of this
# module from that point on.
#
# Systematic coverage of this book starts at SN 35.1, the first
# discourse of Aniccavagga, this saṃyutta's own first vagga. HEAD is
# the nearest already-published page immediately before this module's
# first new page -- SN 34.55, this project's own closing discourse of
# Book III (Khandhavagga), whose own "next" link (a static field baked
# into its already-built HTML file) still points to SN 35.28, the old
# placeholder hand-off target from before this module began. SN 34.55's
# own next must be hand-edited once, right now, to point to SN 35.1 --
# the same one-time fix Book I, Book II, and Book III's own HEAD pages
# each received when their own books began.
#
# TAIL points at the nearest already-published page beyond whatever
# this module currently covers -- moved forward as later vaggas are
# completed, exactly as sn_content_01.py's, sn_content_02.py's, and
# sn_content_03.py's own TAIL were moved across the course of Books
# I-III. It started at SN 35.28, the nearest already-published page
# beyond Aniccavagga (SN 35.1-12); now that Sabbavagga (SN 35.23-32,
# including SN 35.28 itself, mid-vagga) is fully generated, SN 35.28
# is absorbed into this module's own PAGES sequence (hand-patched, not
# auto-chained -- see the fragile-junction note above) and TAIL moves
# to SN 36.6, the next already-published page beyond this module's own
# current coverage.
HEAD = ("sn-34.55.html", "SN 34.55 &middot; Persistence and What&rsquo;s Conducive")
TAIL = ("sn-36.6.html", "SN 36.6 &middot; An Arrow")
INDEX_EXTRA = [
    ("sn-35.28", "Āditta", "Burning"),
    ("sn-36.6", "Sallatha", "An Arrow"),
    ("sn-41.1", "Saṃyojana", "The Fetter"),
    ("sn-42.8", "Kulaghara (Assāroha)", "A Horn Blower"),
]

# --------------------------------------------------------------------------- #
# SN 35 (Saḷāyatanasaṃyutta, "Linked Discourses on the Six Sense
# Fields") is this project's largest saṃyutta so far: 248 discourses
# across 19 vaggas, confirmed by scanning bilara-data's own root-Pali
# vagga labels rather than any external estimate (SuttaCentral's own
# API summary returned an internally inconsistent range on this
# saṃyutta and should not be trusted here without this cross-check):
#
#   1.  Aniccavagga            SN 35.1-12    (12 discourses)
#   2.  Yamakavagga             SN 35.13-22   (10)
#   3.  Sabbavagga               SN 35.23-32   (10) -- contains the
#                                               pre-existing SN 35.28
#   4.  Jātidhammavagga         SN 35.33-42   (10)
#   5.  Sabbaaniccavagga        SN 35.43-52   (10)
#   6.  Avijjāvagga              SN 35.53-62   (10)
#   7.  Migajālavagga           SN 35.63-73   (11)
#   8.  Gilānavagga              SN 35.74-83   (10)
#   9.  Channavagga              SN 35.84-93   (10)
#   10. Saḷavagga                 SN 35.94-103  (10)
#   11. Yogakkhemivagga         SN 35.104-113 (10)
#   12. Lokakāmaguṇavagga       SN 35.114-123 (10)
#   13. Gahapativagga            SN 35.124-133 (10)
#   14. Devadahavagga           SN 35.134-145 (12)
#   15. Navapurāṇavagga         SN 35.146-155 (10)
#   16. Nandikkhayavagga        SN 35.156-167 (12)
#   17. Saṭṭhipeyyālavagga     SN 35.168-227 (60, heavily peyyāla)
#   18. Samuddavagga             SN 35.228-237 (10)
#   19. Āsīvisavagga             SN 35.238-248 (11)
#
# Total: 12+10+10+10+10+10+11+10+10+10+10+10+10+12+10+12+60+10+11=248,
# confirmed against bilara-data's own maximum sutta number (sn35.248).
# Each vagga's own internal structure (individual files vs merged
# peyyāla ranges, unified-prefix vs per-sutta-prefix encoding) must
# still be confirmed independently before writing it -- do not assume
# any later vagga repeats an earlier one's own shape.
# --------------------------------------------------------------------------- #

PAGES = []


def page(samyutta, num, pali, title, **kw):
    """Shared scaffolding for a single discourse of Saḷāyatanavagga.

    Same two-parameter signature as sn_content_01.py's, sn_content_02.py's,
    and sn_content_03.py's own page() (samyutta, then discourse number),
    since this book spans several independently numbered saṃyuttas
    (SN 35, 36, 37...) just as Books I-III did.
    """
    d = {
        "slug": "sn-%d.%d" % (samyutta, num),
        "index_pali": pali,
        "nav_title": title,
        "source": "sn%d/sn%d.%d" % (samyutta, samyutta, num),
        "crumb": "SN %d.%d" % (samyutta, num),
        "number_line": "Saṃyutta Nikāya &middot; Discourse %d.%d" % (samyutta, num),
        "title": title,
        "subtitle": "<em>%ssutta</em>%s" % (
            pali, " &mdash; %s" % kw.pop("vagga") if "vagga" in kw else ""),
    }
    d.update(kw)
    PAGES.append(d)
    return d


def page_range(samyutta, lo, hi, pali, title, **kw):
    """Scaffolding for a single page covering a merged range of discourse
    numbers (a peyyāla block bilara-data itself stores as one file)."""
    d = {
        "slug": "sn-%d.%d-%d" % (samyutta, lo, hi),
        "index_pali": pali,
        "nav_title": title,
        "source": "sn%d/sn%d.%d-%d" % (samyutta, samyutta, lo, hi),
        "crumb": "SN %d.%d&ndash;%d" % (samyutta, lo, hi),
        "number_line": "Saṃyutta Nikāya &middot; Discourses %d.%d&ndash;%d" % (samyutta, lo, hi),
        "title": title,
        "subtitle": "<em>%ssutta</em>%s" % (
            pali, " &mdash; %s" % kw.pop("vagga") if "vagga" in kw else ""),
    }
    d.update(kw)
    PAGES.append(d)
    return d
